const embeddedHandbook=new URLSearchParams(location.search).has('handbook');if(embeddedHandbook)document.body.classList.add('handbook-page');
import {AlgorithmPlayer} from './algorithm-player.js';
import {createCube,parseAlg,inverse,move,apply,drawCube} from './cube.js';
import {$,$$,storage,toast} from './common.js';
let favorites=new Set(storage.get('favorites',[])),data=[],page=0,category='cfop';
let demoPlayer=null;
function previewAlg(alg,size,autoplay=false){try{demoPlayer??=new AlgorithmPlayer($('#algPreview'));demoPlayer.load(alg,size);if(autoplay)demoPlayer.start()}catch(e){toast(e.message)}}
$('#algDialog').addEventListener('close',()=>demoPlayer?.close());
const groupNames={F2L:'F2L · 前两层配对',OLL:'OLL · 顶层定向（57）',PLL:'PLL · 顶层排列（21）',COLL:'COLL · 顶层角块',CMLL:'CMLL · Roux 角块', '2LOLL':'二步 OLL','2LPLL':'二步 PLL','2AOLL':'入门 OLL · 2 个核心公式','2APLL':'入门 PLL · 2 个核心公式','4AOLL':'基础 OLL · 4 个核心公式','4APLL':'基础 PLL · 4 个核心公式',PBL:'PBL · 二阶双层排列',L2E:'L2E · 五阶最后两组棱',L3E:'L3E · 金字塔最后三棱',L4E:'L4E · 金字塔最后四棱',PARITY:'四阶 · 特殊情况'};
const categories={cfop:['F2L','OLL','PLL'],beginner:['2LOLL','2LPLL','2AOLL','2APLL','4AOLL','4APLL'],roux:['CMLL','COLL'],two:['PBL'],big:['PARITY','L2E'],pyraminx:['L3E','L4E']};
const catNames={cfop:'CFOP',beginner:'入门公式',roux:'Roux / COLL',two:'二阶',big:'高阶',pyraminx:'金字塔'};
function saveFav(){storage.set('favorites',[...favorites]);$('#favCount').textContent=favorites.size}
saveFav();
function switchCategory(c){category=c;page=0;$('#tabs').innerHTML=Object.keys(categories).map(k=>`<button data-cat="${k}" class="${k===c?'active':''}">${catNames[k]}</button>`).join('');$('#groupSelect').innerHTML=categories[c].map(g=>`<option value="${g}">${groupNames[g]}</option>`).join('');renderCards()}
function filtered(){const q=$('#search').value.trim().toLowerCase(),g=$('#groupSelect').value;return data.filter(d=>d.group===g&&(!$('#onlyFav').checked||favorites.has(d.id))&&(!q||[d.group,d.name,d.label,...d.algs].join(' ').toLowerCase().includes(q)))}
function puzzleSize(d){return d.group==='PBL'?2:d.group==='PARITY'?4:d.group==='L2E'?5:3}
function isPyraminx(d){return ['L3E','L4E'].includes(d.group)}
function renderCards(){const items=filtered(),max=Math.max(1,Math.ceil(items.length/8));page=Math.min(page,max-1);$('#resultCount').textContent=items.length+' 个局面';$('#algGrid').innerHTML='';for(const d of items.slice(page*8,page*8+8)){const card=document.createElement('article');card.className='alg-card';const favorite=document.createElement('button');favorite.className='favorite'+(favorites.has(d.id)?' saved':'');favorite.textContent=favorites.has(d.id)?'♥':'♡';favorite.setAttribute('aria-label','收藏 '+d.group+' '+d.name);favorite.onclick=()=>{favorites.has(d.id)?favorites.delete(d.id):favorites.add(d.id);saveFav();renderCards()};card.append(favorite);const top=document.createElement('span');top.className='case-top';top.textContent=d.group+' / CASE '+String(d.name).padStart(2,'0');card.append(top);const canvas=document.createElement('canvas');canvas.className='case-canvas';canvas.width=180;canvas.height=180;card.append(canvas);if(!isPyraminx(d)){try{const size=puzzleSize(d),state=apply(createCube(size),inverse(parseAlg(d.algs[0])),size);drawCube(canvas,state,size,-.55,.85)}catch{canvas.style.display='none'}}else{const ctx=canvas.getContext('2d');ctx.fillStyle='#d9e5c3';ctx.beginPath();ctx.moveTo(90,20);ctx.lineTo(22,143);ctx.lineTo(158,143);ctx.closePath();ctx.fill();ctx.fillStyle='#889a72';ctx.font='20px sans-serif';ctx.textAlign='center';ctx.fillText('Pyraminx',90,167);canvas.setAttribute('aria-label','金字塔魔方类别示意图，不是局面图')}
const h=document.createElement('h3');h.textContent=d.group+' '+d.name;card.append(h);const p=document.createElement('div');p.className='case-label';p.textContent=d.label;card.append(p);const formula=document.createElement('div');formula.className='formula';formula.textContent=d.algs[0];card.append(formula);const see=document.createElement('button');see.className='see';see.innerHTML='<span>查看公式'+(isPyraminx(d)?'':'与演示')+'</span><span>↗</span>';see.onclick=()=>showAlg(d);card.append(see);$('#algGrid').append(card)}if(!items.length)$('#algGrid').innerHTML='<p class="empty">还没找到这条公式，换个关键词，或先收藏一个喜欢的局面吧 ♡</p>';$('#pageLabel').textContent=(page+1)+' / '+max;$('#prev').disabled=page===0;$('#next').disabled=page>=max-1;}
$('#tabs').onclick=e=>{if(e.target.dataset.cat)switchCategory(e.target.dataset.cat)};$('#groupSelect').onchange=$('#search').oninput=$('#onlyFav').onchange=()=>{page=0;renderCards()};$('#prev').onclick=()=>{page--;renderCards()};$('#next').onclick=()=>{page++;renderCards()};$('#favorites').onclick=()=>{const d=data.find(d=>favorites.has(d.id));if(d){switchCategory(Object.keys(categories).find(k=>categories[k].includes(d.group)));$('#groupSelect').value=d.group}$('#onlyFav').checked=true;renderCards();toast('切换分类可以查看不同方法的收藏')};
function showAlg(d){demoPlayer?.close();$('#algPreview').hidden=true;$('#algTitle').textContent=d.group+' '+d.name;$('#algDesc').textContent=groupNames[d.group]+' · '+d.label;$('#algOptions').innerHTML='';d.algs.forEach((alg,i)=>{const wrap=document.createElement('div');wrap.className='alg-option';const p=document.createElement('p');p.className='formula';p.textContent=alg;wrap.append(p);const copy=document.createElement('button');copy.className='outline';copy.textContent='复制公式';copy.onclick=async()=>{try{await navigator.clipboard.writeText(alg);toast('公式已放进口袋 ♡')}catch{toast('请选中公式文字复制')}};wrap.append(copy);if(!isPyraminx(d)){const play=document.createElement('button');play.className='primary';play.style.marginLeft='10px';play.textContent='逐步演示 →';play.onclick=()=>previewAlg(alg,puzzleSize(d),true);wrap.append(play)}else{const note=document.createElement('p');note.textContent='金字塔公式可查阅和收藏；当前互动演示支持立方体魔方。';wrap.append(note)}$('#algOptions').append(wrap)});$('#algDialog').showModal();if(!isPyraminx(d))previewAlg(d.algs[0],puzzleSize(d))}
try{data=await(await fetch('algs.json')).json();data.push({id:'parity-oll',group:'PARITY',name:'OLL Parity',label:'单组棱翻转 · Rw 表示右侧两层',algs:["Rw U2 x Rw U2 Rw U2 Rw' U2 Lw U2 Rw' U2 Rw U2 Rw' U2 Rw'"]},{id:'parity-pll',group:'PARITY',name:'PLL Parity',label:'两组棱对换 · Rw 表示右侧两层',algs:["Rw2 R2 U2 Rw2 R2 Uw2 Rw2 R2 Uw2"]});$('#total').textContent=data.length+' 个收录局面';switchCategory('cfop')}catch{$('#total').textContent='公式暂时无法加载';$('#algGrid').innerHTML='<p class="empty">加载失败，请刷新页面再试。互动练习与教程仍然可用。</p>'}

if(new URLSearchParams(location.search).has('favorites'))$('#favorites').click();
document.addEventListener('keydown',e=>{if(e.key==='/'&&!['INPUT','SELECT'].includes(e.target.tagName)){e.preventDefault();$('#search').focus()}});

if(embeddedHandbook){
 window.addEventListener('message',event=>{if(event.origin!==location.origin||event.source!==parent)return;if(event.data?.type==='handbook-close'){$$('dialog[open]').forEach(dialog=>dialog.close());demoPlayer?.close()}else if(event.data?.type==='handbook-favorites')$('#favorites').click()});
 document.addEventListener('keydown',event=>{if(event.key==='Escape'&&!$('dialog[open]')){event.preventDefault();parent.postMessage({type:'handbook-dismiss'},location.origin)}});
}
